window.MOTIF_CATALOG_CHUNKS[13]={"cards":[{"id":"ML-T01339","row_version":2,"title":"계급·소속","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"사회적 계층과 집단 소속은 사람의 지위, 권리, 자원 접근, 관계망을 좌우한다. 인물을 분류할 때는 일시적인 직업이나 친분보다 지속적인 지위와 소속의 효력을 본다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"계급·소속","entry_url":"cards/ML-T01339/index.html"},{"id":"ML-T01340","row_version":2,"title":"신분제 사회","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01339","tag_path":[],"summary":"출생이나 법적 신분에 따라 권리와 의무가 구분되고 계층 간 이동이 제한되는 사회 구조다. 계층 차이만 묘사하는 경우와 달리 신분이 제도적으로 고정되고 불평등을 재생산하는지 살핀다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"신분제 사회","entry_url":"cards/ML-T01340/index.html"},{"id":"ML-T01341","row_version":2,"title":"계급 이동","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01339","tag_path":[],"summary":"개인이나 집단이 사회적 지위 또는 계층을 바꾸는 과정으로, 교육·재산·혼인·공적 심사 등이 통로가 될 수 있다. 단순한 권력 획득이나 일시적 부의 증가는 지위 변화가 사회적으로 인정되는지 확인해 구별한다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"계급 이동","entry_url":"cards/ML-T01341/index.html"},{"id":"ML-T01342","row_version":2,"title":"세습 특권","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01339","tag_path":[],"summary":"특정 가문이나 집단이 출생을 통해 권리, 재산, 직위 같은 이점을 이어받는 구조다. 개인이 얻은 보상이나 관직과 구별해 혜택이 세대를 넘어 자동으로 승계되는지 본다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"세습 특권","entry_url":"cards/ML-T01342/index.html"},{"id":"ML-T01343","row_version":3,"title":"시민권","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01339","tag_path":[],"summary":"정치 공동체의 구성원으로 인정되어 법적 권리와 의무를 부여받는 지위다. 거주 허가나 민족적 정체성과 혼동하지 말고, 제도가 구성원 자격과 그에 따른 권한을 규정하는지 살핀다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"시민권","entry_url":"cards/ML-T01343/index.html"},{"id":"ML-T01344","row_version":3,"title":"추방 제도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01339","tag_path":[],"summary":"권력이나 공동체가 개인 또는 집단의 거주·참여를 금지하고 일정 영역 밖으로 내보내는 제도다. 자발적 이주나 전투 중 후퇴와 구별해 추방이 공식적 처분이나 지속적인 배제 수단으로 작동하는지 본다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"추방 제도","entry_url":"cards/ML-T01344/index.html"},{"id":"ML-T01345","row_version":2,"title":"노예제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01339","tag_path":[],"summary":"사람을 재산처럼 소유하고 강제로 노동시키거나 이동과 선택을 통제하는 제도다. 가혹한 고용이나 일시적 포로 상태와 구별해 소유권과 강제 종속이 지속적으로 인정되는지 확인한다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"노예제","entry_url":"cards/ML-T01345/index.html"},{"id":"ML-T01346","row_version":3,"title":"길드 체계","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01339","tag_path":[],"summary":"동업자나 숙련 노동자가 직업별 조직을 이루어 가입, 훈련, 생산, 거래의 규칙을 관리하는 체계다. 단순한 상인 무리나 친목 모임이 아니라 직업 진입과 시장 활동에 조직의 규율이 실질적 권한을 갖는지 본다.","accent":"#8B795E","tab":"#778F70","facet":"사회·문화·생활","bookmark":"길드 체계","entry_url":"cards/ML-T01346/index.html"},{"id":"ML-T01347","row_version":2,"title":"법·통제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"법과 행정, 감시와 제재가 사람들의 행동을 규율하고 질서를 유지하는 방식이다. 개별 규칙이나 폭력 사건만 다루지 말고 통제 권한을 가진 주체와 그 권한의 작동 범위를 함께 본다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"법·통제","entry_url":"cards/ML-T01347/index.html"},{"id":"ML-T01348","row_version":2,"title":"재판 제도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01347","tag_path":[],"summary":"분쟁이나 혐의를 심리해 사실과 책임을 판단하고 판결을 내리는 공식 절차와 기관이다. 사적 복수나 즉결 처분과 구별해 증거·심리·판단을 담당하는 절차가 마련되어 있는지 살핀다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"재판 제도","entry_url":"cards/ML-T01348/index.html"},{"id":"ML-T01349","row_version":2,"title":"처벌 제도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01347","tag_path":[],"summary":"규칙 위반에 어떤 제재를 부과할지 정하고 집행하는 제도다. 사회적 비난이나 우발적 보복과 구별해 위반과 제재의 관계가 규칙으로 정해지고 권한 있는 주체가 집행하는지 본다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"처벌 제도","entry_url":"cards/ML-T01349/index.html"},{"id":"ML-T01350","row_version":2,"title":"감시 체제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01347","tag_path":[],"summary":"개인과 집단의 행동이나 정보를 지속적으로 관찰·수집해 통제에 활용하는 체계다. 한 번의 미행이나 우연한 목격보다 감시가 조직적이고 반복되며 제재나 의사결정과 연결되는지 확인한다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"감시 체제","entry_url":"cards/ML-T01350/index.html"},{"id":"ML-T01351","row_version":2,"title":"검열 제도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01347","tag_path":[],"summary":"표현·정보의 제작이나 유통을 사전에 심사하거나 사후에 제한하는 제도다. 개인의 자기 검열이나 비판적 반응과 달리, 권한을 가진 주체가 기준과 절차를 통해 유통을 통제하는지 본다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"검열 제도","entry_url":"cards/ML-T01351/index.html"},{"id":"ML-T01352","row_version":2,"title":"비밀경찰","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01347","tag_path":[],"summary":"정권이나 국가 권력이 반대 세력을 찾아내고 정치적 위협을 억누르기 위해 운영하는 비공개 치안 조직이다. 일반 경찰의 통상 업무나 사적인 첩보 활동과 구별해 정치적 감시·탄압이 조직의 핵심 임무인지 살핀다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"비밀경찰","entry_url":"cards/ML-T01352/index.html"},{"id":"ML-T01353","row_version":3,"title":"자경단","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01347","tag_path":[],"summary":"공식 치안 기관이 아닌 주민이나 민간인이 자체적으로 순찰과 제재를 수행하는 집단이다. 단순한 공동체 경계 활동과 구별해 법적 권한 밖의 강제력 행사나 질서 집행이 조직적으로 이뤄지는지 본다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"자경단","entry_url":"cards/ML-T01353/index.html"},{"id":"ML-T01354","row_version":2,"title":"무법 상태","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01347","tag_path":[],"summary":"공통으로 인정되고 집행되는 법과 공권력이 약화되거나 사라져 분쟁을 조정할 권위가 불분명한 상태다. 범죄가 많거나 전쟁 중이라는 사실만으로 단정하지 말고 규칙을 집행하고 안전을 보장할 체계가 실제로 기능하지 않는지 확인한다.","accent":"#8B795E","tab":"#8B739C","facet":"사회·문화·생활","bookmark":"무법 상태","entry_url":"cards/ML-T01354/index.html"},{"id":"ML-T01355","row_version":2,"title":"경제·생산","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"재화와 서비스를 만들고 나누며 소비하는 생산·교환 관계와 그 조직 방식이다. 개인의 부나 특정 상품에만 초점을 두지 말고 누가 생산수단을 통제하고 가치와 자원이 어떻게 배분되는지 살핀다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"경제·생산","entry_url":"cards/ML-T01355/index.html"},{"id":"ML-T01356","row_version":2,"title":"화폐경제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"화폐를 교환과 가격 책정의 일반 수단으로 삼아 재화와 노동을 거래하는 경제 구조다. 동전이나 지폐의 등장만으로 판단하지 말고 화폐가 널리 통용되어 거래와 가치 비교를 매개하는지 본다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"화폐경제","entry_url":"cards/ML-T01356/index.html"},{"id":"ML-T01357","row_version":2,"title":"물물교환","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"화폐 대신 재화나 서비스를 직접 맞바꾸는 교환 방식이다. 선물이나 일방적 공납과 구별해 당사자 사이에 상응하는 물품·노동의 교환이 성립하는지 확인한다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"물물교환","entry_url":"cards/ML-T01357/index.html"},{"id":"ML-T01358","row_version":2,"title":"배급경제","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"중앙 권력이나 정해진 기관이 물자와 소비량을 배정해 분배하는 경제 체계다. 일시적인 구호품 지급과 구별해 배급이 생산·유통의 상시적인 관리 원리로 운영되는지 살핀다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"배급경제","entry_url":"cards/ML-T01358/index.html"},{"id":"ML-T01359","row_version":3,"title":"채무 제도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"빌린 자원이나 돈을 갚아야 할 의무를 계약·관습·법으로 정하고 집행하는 체계다. 단순한 약속이나 호의와 달리 채권자의 권리와 미상환에 따른 결과가 사회적으로 인정되는지 본다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"채무 제도","entry_url":"cards/ML-T01359/index.html"},{"id":"ML-T01360","row_version":2,"title":"상속 제도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"사망이나 승계 시 재산·권리·직위가 누구에게 어떤 규칙으로 이전되는지 정하는 제도다. 살아 있는 동안의 증여나 임명과 구별해 사후 승계의 대상과 순서를 규율하는지 확인한다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"상속 제도","entry_url":"cards/ML-T01360/index.html"},{"id":"ML-T01361","row_version":2,"title":"자원 독점","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"한 개인이나 집단이 특정 자원에 대한 접근·생산·유통을 지배해 다른 이들의 이용을 제한하는 상태다. 단순한 희소성이나 일시적 우위를 넘어 통제력이 경쟁과 배분을 좌우하는지 본다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"자원 독점","entry_url":"cards/ML-T01361/index.html"},{"id":"ML-T01362","row_version":2,"title":"노동 분업","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"생산 과정을 여러 작업으로 나누어 개인이나 집단마다 맡는 역할을 달리하는 방식이다. 숙련의 차이나 직업 목록만 제시하는 경우와 구별해 작업의 분화가 협업과 생산 구조를 어떻게 조직하는지 살핀다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"노동 분업","entry_url":"cards/ML-T01362/index.html"},{"id":"ML-T01363","row_version":2,"title":"장인 생산","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01355","tag_path":[],"summary":"숙련된 개인이나 소규모 작업장이 도구와 기술을 활용해 물건을 만드는 생산 방식이다. 대량 생산과 구별되는 핵심은 규모만이 아니라 제작자의 숙련과 재량이 생산 과정에 직접 반영되는지다.","accent":"#8B795E","tab":"#A58A4E","facet":"사회·문화·생활","bookmark":"장인 생산","entry_url":"cards/ML-T01363/index.html"},{"id":"ML-T01364","row_version":2,"title":"조직·기관","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"공동의 목적을 수행하도록 사람과 권한, 규칙을 지속적으로 배치한 조직체다. 일시적으로 모인 인물이나 느슨한 관계망과 달리 역할과 운영 방식이 안정적으로 유지되는지 본다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"조직·기관","entry_url":"cards/ML-T01364/index.html"},{"id":"ML-T01365","row_version":2,"title":"학교 조직","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"교육과 학습을 맡기 위해 교사·학습자·운영 권한과 교육 규칙을 갖춘 조직이다. 개인 교습이나 일회성 훈련과 구별해 교육의 제공과 운영이 지속적인 조직의 기능인지 확인한다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"학교 조직","entry_url":"cards/ML-T01365/index.html"},{"id":"ML-T01366","row_version":3,"title":"종교 조직","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"신앙의 가르침과 공동체 활동, 의례를 지속적으로 운영하는 종교 단체다. 신앙을 가진 개인이나 일회성 예배와 달리 구성원·권위·활동 규칙을 갖춘 조직인지 살핀다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"종교 조직","entry_url":"cards/ML-T01366/index.html"},{"id":"ML-T01367","row_version":2,"title":"군대 조직","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"무력 방위나 전투를 위해 지휘 체계와 규율, 병력 편제를 갖춘 조직이다. 무장한 개인이나 임시 전투 집단과 구별해 지속적인 지휘·훈련·임무 체계가 있는지 본다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"군대 조직","entry_url":"cards/ML-T01367/index.html"},{"id":"ML-T01368","row_version":2,"title":"기업 조직","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"재화나 서비스를 생산·판매하고 수익과 운영을 관리하는 사업 조직이다. 상거래에 참여하는 개인과 달리 역할 분담과 의사결정 구조를 갖추고 지속적으로 사업을 수행하는지 살핀다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"기업 조직","entry_url":"cards/ML-T01368/index.html"},{"id":"ML-T01369","row_version":2,"title":"범죄 조직","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"불법 행위를 공동으로 수행하거나 통제하기 위해 역할과 관계망을 조직한 집단이다. 함께 범죄를 저지른 우발적 무리와 구별해 지속적인 협력 구조나 내부 규율이 있는지 확인한다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"범죄 조직","entry_url":"cards/ML-T01369/index.html"},{"id":"ML-T01370","row_version":2,"title":"비밀결사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"구성원과 목적, 활동을 외부에 감추고 제한된 참여자끼리 운영하는 결사 조직이다. 비공개 모임과 구별해 가입이나 정보 접근을 통제하고 공동의 활동을 지속적으로 수행하는지 본다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"비밀결사","entry_url":"cards/ML-T01370/index.html"},{"id":"ML-T01371","row_version":2,"title":"연구기관","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"연구를 수행하고 지식이나 기술을 축적·검증하도록 구성된 기관이다. 연구하는 개인이나 임시 조사팀과 구별해 전문 인력, 자원, 절차가 지속적인 연구 활동을 뒷받침하는지 살핀다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"연구기관","entry_url":"cards/ML-T01371/index.html"},{"id":"ML-T01372","row_version":2,"title":"모험가 조직","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01364","tag_path":[],"summary":"탐험·의뢰 수행·위험 지역 활동 등을 위해 모험가들이 가입하고 활동을 조정하는 조직이다. 함께 여행하는 일행과 구별해 회원 관리, 의뢰 중개, 보상이나 규율 같은 지속적 기능이 있는지 본다.","accent":"#8B795E","tab":"#528982","facet":"사회·문화·생활","bookmark":"모험가 조직","entry_url":"cards/ML-T01372/index.html"},{"id":"ML-T01373","row_version":4,"title":"종교·의례","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"초월적 존재나 신념과 관련된 의례가 공동체의 규칙과 관습 속에서 수행되는 방식이다. 개인의 신념이나 세속적 기념 행사와 구별해 종교적 의미와 반복되는 의례 절차가 있는지 살핀다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"종교·의례","entry_url":"cards/ML-T01373/index.html"},{"id":"ML-T01374","row_version":3,"title":"신앙생활","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"사람이 신앙의 가르침과 관행을 일상 속에서 따르고 공동체 활동에 참여하는 생활 방식이다. 한 번의 의례나 신념의 선언과 구별해 신앙이 반복되는 실천과 생활 규범으로 이어지는지 본다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"신앙생활","entry_url":"cards/ML-T01374/index.html"},{"id":"ML-T01375","row_version":3,"title":"제사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"신이나 조상 등에게 예를 올리고 제물이나 기도를 바치는 정해진 의식이다. 일상적인 기도나 추모와 구별해 대상에게 봉헌하고 공동체가 정한 절차를 수행하는지 확인한다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"제사","entry_url":"cards/ML-T01375/index.html"},{"id":"ML-T01376","row_version":2,"title":"장례","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"사망자를 보내고 남은 이들이 죽음을 처리하는 절차와 관습이다. 단순한 매장이나 화장 행위에 한정하지 말고 애도, 장례 의식, 사후 처리의 사회적 규범까지 포함되는지 살핀다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"장례","entry_url":"cards/ML-T01376/index.html"},{"id":"ML-T01377","row_version":3,"title":"혼례","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"혼인 관계의 성립을 당사자와 공동체가 인정하고 알리는 의식과 절차다. 연애나 동거와 구별해 결합이 가족·법·관습상의 지위로 공식화되는지 본다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"혼례","entry_url":"cards/ML-T01377/index.html"},{"id":"ML-T01378","row_version":3,"title":"성년식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"어린이나 청소년이 성인으로 인정되는 전환을 알리고 새 권리·책임을 부여하는 의식이다. 생물학적 성장이나 생일과 구별해 공동체가 성인 지위를 선언하고 그에 따른 역할 변화를 인정하는지 확인한다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"성년식","entry_url":"cards/ML-T01378/index.html"},{"id":"ML-T01379","row_version":2,"title":"즉위식","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"새 통치자가 권력을 이어받았음을 공개적으로 선포하고 정당성을 부여하는 의식이다. 왕위 계승 자체와 구별해 의례가 통치권의 공식 인정이나 공표를 수행하는지 살핀다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"즉위식","entry_url":"cards/ML-T01379/index.html"},{"id":"ML-T01380","row_version":2,"title":"순례","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"종교적으로 중요한 장소를 찾아가 예배·속죄·서원 같은 목적을 수행하는 여정이다. 일반 관광이나 이주와 구별해 방문이 신앙적 의무나 헌신의 실천으로 의미화되는지 본다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"순례","entry_url":"cards/ML-T01380/index.html"},{"id":"ML-T01381","row_version":4,"title":"축제 의례","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01373","tag_path":[],"summary":"축제의 일정과 공동체 관습에 따라 반복되는 의식이나 행렬, 봉헌 같은 행위다. 축제의 오락·공연과 구별해 행위에 정해진 의례적 의미와 절차가 부여되는지 확인한다.","accent":"#8B795E","tab":"#7D8FA3","facet":"사회·문화·생활","bookmark":"축제 의례","entry_url":"cards/ML-T01381/index.html"},{"id":"ML-T01382","row_version":3,"title":"생활·돌봄","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"먹고 입고 거주하며 돌보는 일상적 활동과 이를 가능하게 하는 관습·관계의 방식이다. 개별 물건의 외형보다 일상 유지와 돌봄이 누구의 역할과 규칙으로 운영되는지 살핀다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"생활·돌봄","entry_url":"cards/ML-T01382/index.html"},{"id":"ML-T01383","row_version":4,"title":"식문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"음식의 재료와 조리법, 식사 예절, 함께 먹는 관습을 아우르는 생활 방식이다. 메뉴나 요리 기술 하나에 한정하지 말고 음식 선택과 식사가 공동체의 규범·환경과 어떻게 연결되는지 본다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"식문화","entry_url":"cards/ML-T01383/index.html"},{"id":"ML-T01384","row_version":2,"title":"주거문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"집과 거주 공간을 만들고 사용하며 가족·이웃과 공간을 나누는 관습이다. 건축 양식만을 가리키지 않고 주거 형태와 공간 이용이 생활 방식과 사회 관계를 어떻게 반영하는지 살핀다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"주거문화","entry_url":"cards/ML-T01384/index.html"},{"id":"ML-T01385","row_version":2,"title":"의복문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"옷의 제작과 착용, 관리, 상황별 복장 규범을 포함하는 생활 관습이다. 의상의 시각적 디자인만 다루는 경우와 구별해 복장이 신분·기후·직업·예절과 맺는 관계를 본다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"의복문화","entry_url":"cards/ML-T01385/index.html"},{"id":"ML-T01386","row_version":4,"title":"양육 관습","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"아이를 보호하고 가르치며 성장에 필요한 책임을 나누는 관습과 규범이다. 양육자의 개인 성향이나 일시적 돌봄과 구별해 반복되는 역할 배분과 공동체의 기대가 드러나는지 살핀다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"양육 관습","entry_url":"cards/ML-T01386/index.html"},{"id":"ML-T01387","row_version":3,"title":"교육 관습","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"지식과 기술을 가르치고 배우는 방식이 가정이나 공동체에서 반복되는 관습이다. 공식 학교 제도와 구별해 누구에게 무엇을 어떤 관계와 절차로 전수하는지 본다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"교육 관습","entry_url":"cards/ML-T01387/index.html"},{"id":"ML-T01388","row_version":3,"title":"의료 관습","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"질병과 부상을 예방·진단·치료하고 건강을 돌보는 방식이 생활 속에서 관습화된 형태다. 개별 치료 행위나 전문 의료기관과 구별해 건강 관리가 공동체의 반복되는 규범과 실천으로 자리 잡았는지 살핀다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"의료 관습","entry_url":"cards/ML-T01388/index.html"},{"id":"ML-T01389","row_version":2,"title":"노인 돌봄","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"노인 돌봄은 고령자의 건강과 일상생활을 가족, 지역사회, 기관이 지원하는 활동이다. 작품에서는 돌봄의 주체와 비용, 당사자의 선택권이 어떻게 나뉘는지 드러날 때 적용한다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"노인 돌봄","entry_url":"cards/ML-T01389/index.html"},{"id":"ML-T01390","row_version":3,"title":"공동체 노동","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01382","tag_path":[],"summary":"공동체 노동은 구성원들이 공동의 필요를 위해 노동과 책임을 나누는 방식이다. 단순히 여러 사람이 함께 일하는 장면이 아니라, 참여와 분배가 공동체의 관계나 규칙에 의해 조직될 때 해당한다.","accent":"#8B795E","tab":"#A07A87","facet":"사회·문화·생활","bookmark":"공동체 노동","entry_url":"cards/ML-T01390/index.html"},{"id":"ML-T01391","row_version":3,"title":"문화·규범","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"문화·규범은 한 사회에서 공유되는 관습과 기대가 구성원의 행동을 이끄는 기준으로 작동하는 양상이다. 작품에서는 구체적인 규칙이나 관습이 행동을 허용·제약하는 경우에 적용하며, 단순한 분위기나 개인 취향과 구별한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"문화·규범","entry_url":"cards/ML-T01391/index.html"},{"id":"ML-T01392","row_version":2,"title":"예절","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"예절은 상황과 관계에 맞는 말투와 행동을 정해 원활한 상호작용을 돕는 관습적 기준이다. 작품에서는 인사, 호칭, 식사 행동 같은 규칙의 준수나 위반이 관계에 영향을 줄 때 적용한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"예절","entry_url":"cards/ML-T01392/index.html"},{"id":"ML-T01393","row_version":2,"title":"명예 규범","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"명예 규범은 개인이나 집단의 평판을 지키고 훼손에 대응하도록 요구하는 사회적 기준이다. 작품에서는 체면이나 평판이 실제 선택과 제재를 좌우할 때 적용하며, 개인의 자존감만을 뜻하는 경우와 구별한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"명예 규범","entry_url":"cards/ML-T01393/index.html"},{"id":"ML-T01394","row_version":3,"title":"선물 관습","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"선물 관습은 선물의 주고받기가 호의와 의무, 관계의 위계를 표현하는 사회적 교환 방식이다. 작품에서는 선물의 시기와 가치, 답례 여부가 관계의 의미나 부담을 만드는 경우에 적용한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"선물 관습","entry_url":"cards/ML-T01394/index.html"},{"id":"ML-T01395","row_version":3,"title":"환대 관습","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"환대 관습은 방문자나 낯선 이를 맞아들이고 음식·공간·보호를 제공하는 관례적 방식이다. 작품에서는 손님을 대하는 기대와 거절·수용의 결과가 관계나 지위에 영향을 줄 때 적용한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"환대 관습","entry_url":"cards/ML-T01395/index.html"},{"id":"ML-T01396","row_version":4,"title":"금식 관습","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"금식 관습은 종교적·사회적 이유로 정해진 기간이나 상황에 음식 또는 특정 행위를 삼가는 실천이다. 작품에서는 금식의 규칙과 참여 여부가 생활 리듬이나 공동체 소속을 드러낼 때 적용하며, 일시적인 식사 거르기와 구별한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"금식 관습","entry_url":"cards/ML-T01396/index.html"},{"id":"ML-T01397","row_version":3,"title":"성별 규범","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"성별 규범은 성별에 따라 기대되는 역할, 행동, 권리와 표현을 정하는 사회적 기준이다. 작품에서는 이런 기대가 인물의 선택이나 대우를 제한하거나 형성할 때 적용하며, 개인의 성 정체성 자체와 구별한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"성별 규범","entry_url":"cards/ML-T01397/index.html"},{"id":"ML-T01398","row_version":2,"title":"가족 규범","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"가족 규범은 가족 구성원에게 역할과 의무, 의사결정 권한을 배분하는 관습적 기준이다. 작품에서는 부양, 혼인, 상속, 위계 같은 기대가 가족 관계를 조직할 때 적용하며, 법률상 가족 관계만을 가리키지 않는다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"가족 규범","entry_url":"cards/ML-T01398/index.html"},{"id":"ML-T01399","row_version":3,"title":"외부인 대우","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01391","tag_path":[],"summary":"외부인 대우는 공동체가 소속되지 않은 사람에게 적용하는 환영, 경계, 배제의 관행이다. 작품에서는 출신이나 소속에 따라 접근권과 신뢰, 보호가 달라지는 양상이 나타날 때 적용한다.","accent":"#8B795E","tab":"#79866C","facet":"사회·문화·생활","bookmark":"외부인 대우","entry_url":"cards/ML-T01399/index.html"},{"id":"ML-T01400","row_version":2,"title":"놀이·여가","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"group","parent_id":"ML-F15","tag_path":[],"summary":"놀이·여가는 생업과 의무에서 벗어나 즐거움이나 휴식을 위해 이루어지는 활동과 그 사회적 방식이다. 작품에서는 활동 자체뿐 아니라 참여 기회와 여가 시간의 배분이 생활이나 관계에 영향을 줄 때 적용한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"놀이·여가","entry_url":"cards/ML-T01400/index.html"},{"id":"ML-T01401","row_version":3,"title":"스포츠 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01400","tag_path":[],"summary":"스포츠 문화는 신체 경기와 훈련을 둘러싼 규칙, 관람, 응원, 소속감이 공유되는 사회적 양상이다. 작품에서는 경기의 수행만이 아니라 선수·관중·팀을 둘러싼 관습과 관계가 중요하게 작동할 때 적용한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"스포츠 문화","entry_url":"cards/ML-T01401/index.html"},{"id":"ML-T01402","row_version":3,"title":"도박 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01400","tag_path":[],"summary":"도박 문화는 금전이나 가치물을 걸고 우연 또는 기술의 결과를 겨루는 활동을 둘러싼 관행과 관계망이다. 작품에서는 내기 방식과 위험 부담, 참여를 둘러싼 사회적 태도가 서사에 작용할 때 적용하며, 단순한 경쟁이나 보상 체계와 구별한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"도박 문화","entry_url":"cards/ML-T01402/index.html"},{"id":"ML-T01403","row_version":3,"title":"보드게임 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01400","tag_path":[],"summary":"보드게임 문화는 보드와 말, 규칙을 사용하는 게임을 함께 즐기며 형성되는 관습과 교류 방식이다. 작품에서는 게임의 규칙뿐 아니라 모임, 승패의 처리, 참여자 간 상호작용이 핵심일 때 적용한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"보드게임 문화","entry_url":"cards/ML-T01403/index.html"},{"id":"ML-T01404","row_version":3,"title":"축제 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01400","tag_path":[],"summary":"축제 문화는 정해진 시기나 계기를 공동으로 기념하며 의례, 놀이, 소비와 모임을 펼치는 관행이다. 작품에서는 반복되는 행사와 집단 참여가 공동체의 시간 감각이나 소속을 드러낼 때 적용한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"축제 문화","entry_url":"cards/ML-T01404/index.html"},{"id":"ML-T01405","row_version":3,"title":"공연 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01400","tag_path":[],"summary":"공연 문화는 무대나 공개된 자리에서 공연을 만들고 관람하며 참여하는 관습과 제도다. 작품에서는 공연자와 관객의 역할, 관람 방식, 접근 조건이 사회적 의미를 가질 때 적용한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"공연 문화","entry_url":"cards/ML-T01405/index.html"},{"id":"ML-T01406","row_version":2,"title":"관광 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01400","tag_path":[],"summary":"관광 문화는 일상 거주지를 벗어나 장소를 방문하고 그곳을 경험·소비하는 관행과 산업적 관계를 가리킨다. 작품에서는 방문자의 이동과 지역 주민의 삶, 장소를 둘러싼 기대가 서로 영향을 줄 때 적용한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"관광 문화","entry_url":"cards/ML-T01406/index.html"},{"id":"ML-T01407","row_version":2,"title":"수집 문화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":"tag","parent_id":"ML-T01400","tag_path":[],"summary":"수집 문화는 특정 물건이나 자료를 모으고 분류·보존·교환하며 가치를 부여하는 관행이다. 작품에서는 수집 대상의 의미와 소유·교환이 인물의 정체성이나 사회적 관계를 형성할 때 적용한다.","accent":"#8B795E","tab":"#AF8665","facet":"사회·문화·생활","bookmark":"수집 문화","entry_url":"cards/ML-T01407/index.html"},{"id":"ML-T01408","row_version":2,"title":"무기·방어구","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"group","parent_id":"ML-F16","tag_path":[],"summary":"무기와 방어구는 공격하거나 공격을 막기 위해 사용하는 물건으로, 전투에서 인물의 수단과 보호 수준을 드러낸다. 장면의 핵심이 공격 도구나 신체 보호 장비의 사용·획득·파괴에 있을 때 적용하며, 단순한 소품이나 전투 능력 자체와는 구분한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"무기·방어구","entry_url":"cards/ML-T01408/index.html"},{"id":"ML-T01409","row_version":2,"title":"검","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"검은 날이 선 칼날을 손에 쥐고 휘두르거나 찔러 공격하는 무기다. 칼날 무기라는 형태가 장면의 선택이나 사용 방식에 중요할 때 적용하며, 단검이나 도끼 등 다른 날붙이는 별도로 본다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"검","entry_url":"cards/ML-T01409/index.html"},{"id":"ML-T01410","row_version":2,"title":"창","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"창은 긴 자루 끝의 뾰족한 촉으로 찌르거나 던져 공격하는 무기다. 긴 사거리나 찌르기 방식이 전투의 전개에 영향을 줄 때 적용하며, 활처럼 발사체를 쏘는 무기와 구별한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"창","entry_url":"cards/ML-T01410/index.html"},{"id":"ML-T01411","row_version":2,"title":"활","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"활은 시위를 당겼다 놓아 화살을 멀리 쏘는 무기다. 조준과 발사, 화살의 비축이나 회수가 장면에 작용할 때 적용하며, 총기나 투척 무기에는 적용하지 않는다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"활","entry_url":"cards/ML-T01411/index.html"},{"id":"ML-T01412","row_version":2,"title":"총기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"총기는 화약이나 그에 준하는 추진력으로 탄환을 발사하는 무기다. 발사·장전·탄약 또는 총성의 효과가 장면의 작동 방식에 포함될 때 적용하며, 폭발물이나 활처럼 탄환을 발사하지 않는 무기와 구분한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"총기","entry_url":"cards/ML-T01412/index.html"},{"id":"ML-T01413","row_version":2,"title":"폭발물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"폭발물은 화학 반응이나 점화로 급격한 에너지와 파괴력을 내는 물질 또는 장치다. 설치·투척·기폭과 폭발의 범위가 사건에 중요할 때 적용하며, 총기 탄약처럼 발사체로 쓰이는 것과 단순한 화재는 구별한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"폭발물","entry_url":"cards/ML-T01413/index.html"},{"id":"ML-T01414","row_version":2,"title":"방패","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"방패는 손이나 팔에 들거나 몸에 부착해 공격을 막는 방어 도구다. 막기·밀치기·엄폐 같은 방패의 사용이 인물의 대응을 좌우할 때 적용하며, 몸에 착용하는 갑옷과 구분한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"방패","entry_url":"cards/ML-T01414/index.html"},{"id":"ML-T01415","row_version":2,"title":"갑옷","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"갑옷은 몸에 입거나 두르는 보호 장비로, 공격을 막거나 피해를 줄이도록 만들어진다. 착용 여부와 보호 범위가 전투나 인물의 지위에 의미를 가질 때 적용하며, 들고 막는 방패나 장식용 의복과 구분한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"갑옷","entry_url":"cards/ML-T01415/index.html"},{"id":"ML-T01416","row_version":2,"title":"비살상 무기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01408","tag_path":[],"summary":"비살상 무기는 상대를 죽이는 대신 제압하거나 움직임을 제한하도록 설계된 무기다. 사용 목적과 실제 효과가 살해보다 제압에 놓일 때 적용하며, 결과적으로 사망을 일으킨 일반 무기나 맨손 제압과는 구별한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"비살상 무기","entry_url":"cards/ML-T01416/index.html"},{"id":"ML-T01417","row_version":2,"title":"문서·기록","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"group","parent_id":"ML-F16","tag_path":[],"summary":"문서와 기록은 정보나 경험을 문자·이미지·소리 등의 형태로 남겨 보존하거나 전달하는 자료다. 읽거나 찾아내고 조작하는 기록물이 사건의 정보 흐름에 영향을 줄 때 적용하며, 정보를 담지 않는 물건이나 기억 그 자체와는 구분한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"문서·기록","entry_url":"cards/ML-T01417/index.html"},{"id":"ML-T01418","row_version":2,"title":"책","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"책은 여러 쪽의 글이나 이미지가 묶여 읽고 보관할 수 있도록 만든 매체다. 책의 내용, 소유, 열람 또는 분실이 장면에 작용할 때 적용하며, 낱장 문서나 일회성 메모와 구별한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"책","entry_url":"cards/ML-T01418/index.html"},{"id":"ML-T01419","row_version":2,"title":"일기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"일기는 작성자가 날짜나 시간의 흐름에 따라 사적인 생각과 경험을 기록한 글이다. 기록자의 시점이나 당시와 현재의 차이를 드러내는 자료로 기능할 때 적용하며, 수신자를 상정해 보낸 편지나 공식 보고서와 구분한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"일기","entry_url":"cards/ML-T01419/index.html"},{"id":"ML-T01420","row_version":2,"title":"편지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"편지는 특정 수신자에게 생각·정보·요청을 전달하려고 작성한 글이다. 발신과 수신, 전달의 지연이나 누락이 관계와 사건에 영향을 줄 때 적용하며, 개인이 보관하는 일기나 공개 공지와 구분한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"편지","entry_url":"cards/ML-T01420/index.html"},{"id":"ML-T01421","row_version":2,"title":"계약서","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"계약서는 당사자들이 합의한 의무와 권리를 문서로 남기는 기록이다. 서명·조항·위반 여부가 행동을 제약하거나 분쟁의 근거가 될 때 적용하며, 단순한 약속이나 일방이 작성한 편지와 구별한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"계약서","entry_url":"cards/ML-T01421/index.html"},{"id":"ML-T01422","row_version":2,"title":"지도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"지도는 공간의 위치와 관계를 기호나 축척으로 나타내어 길 찾기와 장소 파악을 돕는 자료다. 이동 경로, 미지의 구역, 표시된 장소를 찾는 일이 장면의 목적에 포함될 때 적용하며, 풍경 묘사나 실제 장소 자체와는 구분한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"지도","entry_url":"cards/ML-T01422/index.html"},{"id":"ML-T01423","row_version":2,"title":"족보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"족보는 한 집안의 혈통과 친족 관계를 세대별로 정리한 기록이다. 계보가 신분·상속·혈연의 확인이나 은폐에 쓰일 때 적용하며, 가족의 구술 기억이나 일반적인 명단과 구별한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"족보","entry_url":"cards/ML-T01423/index.html"},{"id":"ML-T01424","row_version":3,"title":"사진","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"사진은 카메라 등으로 특정 순간의 빛을 기록한 이미지다. 촬영된 장면이 증거·기억·정체성의 단서로 기능할 때 적용하며, 그림이나 촬영 장치 자체와 구분한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"사진","entry_url":"cards/ML-T01424/index.html"},{"id":"ML-T01425","row_version":2,"title":"녹음물","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"녹음물은 말이나 소리의 파형을 매체에 기록해 나중에 재생할 수 있게 한 자료다. 재생·편집·청취를 통해 과거의 발언이나 소리를 확인하는 일이 사건에 중요할 때 적용하며, 실시간 통신이나 악보와 구분한다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"녹음물","entry_url":"cards/ML-T01425/index.html"},{"id":"ML-T01426","row_version":3,"title":"금지된 문서","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01417","tag_path":[],"summary":"금지된 문서는 접근이나 열람이 권력·규범·위험에 의해 제한된 기록물이다. 금지 사실과 이를 둘러싼 접근, 은닉, 처벌의 가능성이 서사에서 작동할 때 적용하며, 내용이 단지 비밀스럽거나 낯설다는 이유만으로는 해당하지 않는다.","accent":"#8E8263","tab":"#778F70","facet":"사물·도구·자원","bookmark":"금지된 문서","entry_url":"cards/ML-T01426/index.html"},{"id":"ML-T01427","row_version":2,"title":"열쇠·증표","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"group","parent_id":"ML-F16","tag_path":[],"summary":"열쇠와 증표는 잠금장치를 열거나 권한·소속·자격을 확인하는 데 쓰이는 물건이다. 물건의 소지나 제시가 통과·접근·인정 여부를 바꿀 때 적용하며, 그 기능이 없는 장식품이나 일반 소지품은 제외한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"열쇠·증표","entry_url":"cards/ML-T01427/index.html"},{"id":"ML-T01428","row_version":2,"title":"열쇠","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"열쇠는 자물쇠나 잠금 장치의 구조에 맞춰 이를 열거나 잠그는 도구다. 특정 문·상자·장치에 대한 접근을 가능하게 하거나 막을 때 적용하며, 암호나 권한 증명처럼 물리적 잠금에 맞물리지 않는 수단과 구분한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"열쇠","entry_url":"cards/ML-T01428/index.html"},{"id":"ML-T01429","row_version":3,"title":"가문·단체 문장","original":"","aliases":["문장(紋章)"],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"가문이나 단체 문장은 특정 집단의 정체성과 소속을 나타내는 식별 표식이다. 문양을 알아보거나 표시함으로써 혈통·충성·소속이 확인되는 장면에 적용하며, 개인의 이름표나 공식 인장과 구별한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"가문·단체 문장","entry_url":"cards/ML-T01429/index.html"},{"id":"ML-T01430","row_version":2,"title":"인장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"인장은 문서나 물건에 찍어 발신자·권한·승인을 표시하는 표식 또는 그 도구다. 날인 여부가 문서의 진위나 효력, 소유의 확인에 영향을 줄 때 적용하며, 가문을 장식적으로 나타내는 문장이나 서명과는 구분한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"인장","entry_url":"cards/ML-T01430/index.html"},{"id":"ML-T01431","row_version":3,"title":"신분증","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"신분증은 특정 인물의 신원이나 자격을 확인하도록 발급된 증명물이다. 제시·검사·위조를 통해 인물의 신원이나 접근 권한이 판별될 때 적용하며, 행사 초대장이나 장소 통행증과 구별한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"신분증","entry_url":"cards/ML-T01431/index.html"},{"id":"ML-T01432","row_version":2,"title":"초대장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"초대장은 특정 사람을 행사나 모임에 초대한다는 사실과 조건을 전달하는 표식이다. 초대받았는지 여부가 참석 자격이나 관계의 의미를 가를 때 적용하며, 신원 확인이나 일반 통행을 위한 증명물과 구분한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"초대장","entry_url":"cards/ML-T01432/index.html"},{"id":"ML-T01433","row_version":3,"title":"통행증","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"통행증은 특정 경로나 구역을 지나갈 수 있도록 허가하는 증표다. 검문이나 출입 통제에서 소지가 통과 여부를 결정할 때 적용하며, 신원 확인만을 위한 신분증이나 특정 행사 참석용 초대장과 구별한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"통행증","entry_url":"cards/ML-T01433/index.html"},{"id":"ML-T01434","row_version":2,"title":"왕관","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"왕관은 군주의 지위와 통치 권한을 나타내며 의례나 즉위에서 쓰이는 머리 장식이다. 착용·전달·탈취가 왕권의 승인이나 계승을 상징할 때 적용하며, 단순한 장신구나 일반적인 권력 상징과 구분한다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"왕관","entry_url":"cards/ML-T01434/index.html"},{"id":"ML-T01435","row_version":2,"title":"가보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01427","tag_path":[],"summary":"가보는 한 집안이나 계통에서 대대로 물려 보존하는 물건이다. 전승의 이력과 소유권이 가족의 기억·지위·갈등에 영향을 줄 때 적용하며, 오래되었거나 값비싼 물건이라는 이유만으로는 가보로 보지 않는다.","accent":"#8E8263","tab":"#8B739C","facet":"사물·도구·자원","bookmark":"가보","entry_url":"cards/ML-T01435/index.html"},{"id":"ML-T01436","row_version":3,"title":"의복·장신구","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"group","parent_id":"ML-F16","tag_path":[],"summary":"의복과 장신구는 몸에 걸쳐 보호·실용·장식·신분 표시의 기능을 하는 물건이다. 착용 방식이나 외양이 인물의 활동·정체성·사회적 인식에 구체적으로 작용할 때 적용하며, 신체 특징이나 복장과 무관한 개인 소지품과 구분한다.","accent":"#8E8263","tab":"#A58A4E","facet":"사물·도구·자원","bookmark":"의복·장신구","entry_url":"cards/ML-T01436/index.html"},{"id":"ML-T01437","row_version":3,"title":"가면","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01436","tag_path":[],"summary":"가면은 얼굴을 가리거나 다른 얼굴처럼 보이도록 착용하는 물건이다. 신원 은폐, 역할 수행, 정체성 오인의 핵심 수단으로 쓰일 때 적용하며, 얼굴을 가리는 천이나 분장처럼 착용 가능한 별도 가면이 없는 경우와 구분한다.","accent":"#8E8263","tab":"#A58A4E","facet":"사물·도구·자원","bookmark":"가면","entry_url":"cards/ML-T01437/index.html"},{"id":"ML-T01438","row_version":2,"title":"망토","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":"tag","parent_id":"ML-T01436","tag_path":[],"summary":"망토는 어깨에 걸쳐 몸이나 의복 위를 덮는 겉옷이다. 덮거나 펄럭이는 형태와 착용 방식이 행동이나 외양에 의미를 더할 때 적용하며, 후드 달린 외투 등 다른 의복을 모두 망토로 뭉뚱그리지 않는다.","accent":"#8E8263","tab":"#A58A4E","facet":"사물·도구·자원","bookmark":"망토","entry_url":"cards/ML-T01438/index.html"}]}.cards;